var n=`0853-aloo-paratha`;var t=`world-0853`;var a=`IN`;var o=`south-asia`;var s=4;var r=85;var l={en:`Aloo Paratha`,ua:`Алу паратха`};var d={en:`Aloo Paratha is a India dish made with whole wheat flour, potato, serrano pepper, cilantro. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Алу паратха, страва кухні країни Індія. Основні складники: цільнозернове пшеничне борошно, картопля, перець серрано, кінза. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var g=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 18 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 18 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:18,i:[[`whole-wheat-flour`,390,`g`],[`water`,210,`ml`],[`table-salt`,5,`g`],[`canola-oil`,22,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 20 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 20 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:20,i:[[`potato`,500,`g`],[`water`,850,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`serrano-pepper`,2,`pcs`],[`ground-cumin`,6,`g`],[`cilantro`,24,`g`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:15,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 22 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 22 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:22,i:[[`ghee`,80,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`plain-yogurt`,120,`g`]]}];var h={slug:n,id:t,country:`IN`,region:o,servings:4,minutes:85,title:l,text:d,steps:g};export{a as country,h as default,t as id,r as minutes,o as region,s as servings,n as slug,g as steps,d as text,l as title};